import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { resolve, join } from 'node:path';
const repo=resolve(import.meta.dirname,'..');
const output=resolve(process.argv[2] || join(repo,'work/packaged-home-final'));
const app=join(repo,'release/live-home/mac-arm64/CanvasTTY Live Home Lab.app');
const binary=join(app,'Contents/MacOS/CanvasTTY Live Home Lab');
await mkdir(output,{recursive:true});
const env={...process.env,CANVASTTY_HOME_LAB_SMOKE_OUTPUT:output};
delete env.ELECTRON_RUN_AS_NODE; delete env.CANVASTTY_USER_DATA_DIR;
const launch=spawnSync(binary,[],{env,encoding:'utf8',timeout:55000});
await writeFile(join(output,'app.log'),(launch.stdout ?? '')+(launch.stderr ?? ''));
if(launch.error) throw launch.error;
assert.equal(launch.status,0);
const report=JSON.parse(await readFile(join(output,'verification.json'),'utf8'));
assert.equal(report.profile,join(repo,'release/live-home/Profile'));
assert.equal(report.packaged,true);
const script=`const pty=require(process.argv[1]);const terminal=pty.spawn('/bin/zsh',['-f','-c','printf CT_LAB_PTY_OK'],{name:'xterm-color',cols:80,rows:24,cwd:process.cwd(),env:{PATH:'/usr/bin:/bin'}});let output='';terminal.onData(data=>output+=data);terminal.onExit(event=>{if(event.exitCode!==0||!output.includes('CT_LAB_PTY_OK'))process.exit(1);console.log('PACKAGED_PTY_OK');});setTimeout(()=>process.exit(2),10000).unref();`;
const pty=spawnSync(binary,['-e',script,join(app,'Contents/Resources/app.asar/node_modules/node-pty')],{env:{...env,ELECTRON_RUN_AS_NODE:'1'},encoding:'utf8',timeout:15000});
await writeFile(join(output,'pty.log'),(pty.stdout ?? '')+(pty.stderr ?? ''));
if(pty.error) throw pty.error;
assert.equal(pty.status,0);assert.match(pty.stdout,/PACKAGED_PTY_OK/);
const signature=spawnSync('codesign',['--verify','--deep','--strict',app],{encoding:'utf8',timeout:15000});
assert.equal(signature.status,0,signature.stderr);
Object.assign(report,{packagedPty:'passed',signature:'ad-hoc verified'});
await writeFile(join(output,'verification.json'),JSON.stringify(report,null,2));
console.log('LOCAL_HOME_BUNDLE_OK '+JSON.stringify(report));
